/**
 * Turns n8n's error payload into something readable on a phone at 07:31.
 */
const e = $json.execution ?? {};
const w = $json.workflow ?? {};

const trimmed = String(e.error?.message ?? 'Unknown error').slice(0, 400);

const text = [
  '<b>AI Paper Digest failed</b>',
  '',
  'Workflow: ' + (w.name ?? 'unknown'),
  'Node: <code>' + (e.lastNodeExecuted ?? 'unknown') + '</code>',
  'When: ' + (e.startedAt ?? new Date().toISOString()),
  '',
  '<pre>' + trimmed.replace(/&/g, '&amp;').replace(/</g, '&lt;') + '</pre>',
  '',
  e.url ? '<a href="' + e.url + '">Open the execution</a>' : '',
]
  .filter(Boolean)
  .join('\n');

return [{ json: { text } }];
